import {services,staff,localDay,minutes,clock,book,transition,empty,validate} from './engine.js';
import {captureView,restoreView,installViewportManager} from './view-continuity.js';
import {createOperationGate,connectionMessage} from './ui-state.js?v=20261023-clean1';
const $=s=>document.querySelector(s),key='queueflow-demo-v1';let view='overview',filter='all',search='',date=localDay(),editId=null,pending=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=empty();try{const s=JSON.parse(localStorage.getItem(key));if(s?.version===1&&Array.isArray(s.entries)&&s.settings&&Array.isArray(s.settings.away)&&Array.isArray(s.settings.closedDates))state=s;}catch{}
let cloud=null,cloudMode=false,cloudReady=false,cloudUser=null,cloudStatus='signed-out';const operations=createOperationGate();
const labels={booked:'Scheduled',waiting:'Waiting',serving:'In service',completed:'Completed',cancelled:'Cancelled',noshow:'No-show'};
const serviceFor=e=>services.find(s=>s.id===e.service)||services[0];
const initials=name=>name.split(' ').map(s=>s[0]).slice(0,2).join('').toUpperCase();
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function feedback(message){toast(message);if($('#booking-dialog').open)$('#form-error').textContent=message;$('#workspace-message').textContent=message;$('#workspace-message').hidden=false;}
function connection(){const m=connectionMessage({mode:cloudMode?'cloud':'demo',status:cloudStatus,online:navigator.onLine,busy:operations.busy});$('.connection-banner div').textContent=m.title+' · '+m.detail;$('.connection-banner').hidden=cloudMode&&cloudStatus==='connected'&&navigator.onLine&&!operations.busy;$('.demo-pill').hidden=cloudMode&&cloudStatus==='connected';$('#save-status').textContent=m.title;}
async function mutate(fn){const token=operations.begin();if(!token){feedback('A save is in progress. Please wait.');return false;}$('#workspace-message').hidden=true;connection();try{if(cloudMode){if(!navigator.onLine||!cloudReady)throw Error('Reconnect to your workspace before saving. Your form has been kept.');await cloud.changeWorkspace(fn);}else{const commit=()=>{if(!operations.isCurrent(token))throw Error('Your workspace changed. Try again.');let fresh=empty();const raw=localStorage.getItem(key);if(raw)fresh=JSON.parse(raw);const next=fn(fresh);localStorage.setItem(key,JSON.stringify(next));state=next;};if(!navigator.locks)throw Error('Use an up-to-date browser to safely coordinate changes.');await navigator.locks.request(key,commit);if(operations.isCurrent(token))render();}return operations.isCurrent(token);}catch(e){if(operations.isCurrent(token))feedback(cloudMode&&cloud?cloud.message(e):e.message||'Could not save. Check browser storage.');return false;}finally{if(operations.finish(token))connection();}}
window.addEventListener('storage',e=>{if(!cloudMode&&e.key===key){try{state=e.newValue?JSON.parse(e.newValue):empty();render();}catch{toast('Stored data could not be loaded.');}}});
window.addEventListener('offline',()=>{connection();feedback(cloudMode?'Offline. Cloud changes are paused; your form is kept.':'Offline. Local demo changes can still be saved on this device.');});window.addEventListener('online',()=>{connection();toast(cloudMode?'Connection restored. Waiting for connection confirmation.':'Back online.');});
const todayEntries=()=>state.entries.filter(e=>e.date===localDay());
const status=e=>`<span class="status ${esc(e.status)}">${esc(labels[e.status])}</span>`;
function actions(e){return `<div class="actions">${e.status==='booked'?`<button data-action="waiting" data-id="${e.id}">Check in</button><button data-edit="${e.id}">Edit</button>`:''}${e.status==='waiting'?`<button data-action="serving" data-id="${e.id}">Start →</button>`:''}${e.status==='serving'?`<button data-action="completed" data-id="${e.id}">Complete ✓</button>`:''}${['booked','waiting'].includes(e.status)?`<button data-action="cancelled" data-id="${e.id}" class="danger">Cancel</button><button data-action="noshow" data-id="${e.id}">No-show</button>`:''}</div>`;}
function stats(){const items=todayEntries(),wait=items.filter(e=>e.status==='waiting');return `<div class="stats"><div class="stat"><div class="stat-head"><span>Today’s appointments</span><span>▤</span></div><div class="stat-value">${items.filter(e=>e.status!=='cancelled').length}</div><small>${items.filter(e=>e.status==='booked').length} still scheduled today</small></div><div class="stat highlight"><div class="stat-head"><span>In the queue</span><span>☷</span></div><div class="stat-value">${wait.length.toString().padStart(2,'0')}</div><small>${state.settings.paused?'Check-in is paused':'Ready when you are'}</small></div><div class="stat"><div class="stat-head"><span>Completed today</span><span>✓</span></div><div class="stat-value">${items.filter(e=>e.status==='completed').length.toString().padStart(2,'0')}</div><small>A little more time well spent</small></div><div class="stat"><div class="stat-head"><span>Queued service time</span><span>◷</span></div><div class="stat-value">${wait.reduce((a,e)=>a+serviceFor(e).minutes,0)} <sub>min</sub></div><small>Total workload, not a wait promise</small></div></div>`;}
function appointments(compact=false){let entries=state.entries.filter(e=>e.date===date&&(filter==='all'||e.status===filter)&&`${e.name} ${e.phone} ${e.staff}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>a.time.localeCompare(b.time));const count=entries.length;if(compact)entries=entries.slice(0,6);return `<section class="panel"><div class="panel-title"><div><h2>${compact?'Today’s appointments':'Appointments'}</h2><p>A little organization. A smoother day.</p></div><button class="text-link" data-view="${compact?'appointments':'customer'}">${compact?'View all appointments':'Open booking page'} ↗</button></div><div class="filters"><input id="search" type="search" placeholder="Search customer or team…" aria-label="Search appointments" value="${esc(search)}"><input id="date-filter" type="date" aria-label="Appointment date" value="${date}"></div><div class="tabs">${[['all','All'],['booked','Scheduled'],['waiting','Waiting'],['completed','Completed']].map(([v,l])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${l}</button>`).join('')}<select id="other-status" aria-label="More status filters"><option value="all">More</option>${['serving','cancelled','noshow'].map(v=>`<option value="${v}" ${filter===v?'selected':''}>${labels[v]}</option>`).join('')}</select></div>${entries.length?`<div class="table-scroll"><table><thead><tr><th>CUSTOMER</th><th>TIME / SERVICE</th><th>TEAM</th><th>STATUS</th>${!compact?'<th>ACTIONS</th>':''}</tr></thead><tbody>${entries.map(e=>`<tr><td><div class="customer-cell"><span class="avatar">${esc(initials(e.name))}</span><div><b>${esc(e.name)}</b><small>${esc(e.phone)}</small></div></div></td><td><b>${e.time}</b><small>${serviceFor(e).name} · ${serviceFor(e).minutes} min</small></td><td>${esc(e.staff.split(' ')[0])}<small>${e.ticket?'Ticket #'+e.ticket:'By appointment'}</small></td><td>${status(e)}</td>${!compact?`<td>${actions(e)}</td>`:''}</tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>No appointments here yet.</strong>Book a little breathing room into the day.<p><button class="secondary" data-book>＋ Add an appointment</button></p></div>`}<div class="table-footer">Showing ${entries.length} of ${count} appointments · Device local time</div></section>`;}
function queue(){const items=todayEntries(),serving=items.filter(e=>e.status==='serving'),waiting=items.filter(e=>e.status==='waiting').sort((a,b)=>(a.ticket||0)-(b.ticket||0));return `<section class="panel queue-panel"><div class="panel-title"><div><h2>Live queue</h2><p>One person closer to a great day.</p></div><span class="live">● ${state.settings.paused?'PAUSED':'LOCAL'}</span></div>${serving.length?serving.map(e=>`<div class="serving-card"><div class="overline">NOW SERVING <span class="ticket">#${String(e.ticket).padStart(2,'0')}</span></div><h3>${esc(e.name)}</h3><p>${serviceFor(e).name} · with ${esc(e.staff.split(' ')[0])}</p>${actions(e)}</div>`).join(''):`<div class="serving-card"><div class="overline">READY FOR THE NEXT PERSON</div><h3>A moment to catch your breath.</h3><p>${waiting.length?'Start service for a waiting customer below.':'No customers are currently in service.'}</p></div>`}<div class="queue-label">UP NEXT <span>(${waiting.length})</span></div><div class="queue-list">${waiting.length?waiting.map(e=>`<div class="queue-row"><span class="queue-number">${String(e.ticket).padStart(2,'0')}</span><div><b>${esc(e.name)}</b><small>${serviceFor(e).name} · ${esc(e.staff.split(' ')[0])}</small></div>${actions(e)}</div>`).join(''):'<div class="empty">The queue is clear. You’re all caught up.</div>'}</div><div class="queue-bottom">◷ Queue order follows check-in. Each team member can serve one person at a time. Duration estimates can change.</div></section>`;}
function team(compact=false){if(compact)return `<section class="panel"><div class="panel-title"><h2>Your team today</h2><button class="text-link" data-view="team">Manage team ↗</button></div><div class="team-list">${staff.map(n=>`<div class="team-person"><span class="avatar">${initials(n)}</span><div><b>${n}</b><small>● ${state.settings.away.includes(n)?'Away':todayEntries().some(e=>e.staff===n&&e.status==='serving')?'In service':'Available'}</small></div></div>`).join('')}</div></section>`;return `<div class="settings-grid">${staff.map(n=>`<section class="panel settings-card"><span class="avatar">${initials(n)}</span><h3>${n}</h3><p>${state.settings.away.includes(n)?'Away — new bookings are blocked.':'Available for new appointments.'}<br>${state.entries.filter(e=>e.staff===n&&['booked','waiting','serving'].includes(e.status)).length} active appointments remain. Existing bookings are preserved when availability changes.</p><button class="secondary" data-away="${n}">${state.settings.away.includes(n)?'Mark available':'Mark away'}</button></section>`).join('')}</div>`;}
function settings(){return `<div class="settings-grid"><section class="panel settings-card"><h3>Queue controls</h3><p>Pause new check-ins while your team catches up. Existing customers can still be served.</p><button class="secondary" id="pause-queue">${state.settings.paused?'Resume check-in':'Pause check-in'}</button><label>Maximum active queue size<input id="capacity" type="number" min="1" max="100" value="${state.settings.capacity}"></label><button class="secondary" id="save-capacity">Save capacity</button></section><section class="panel settings-card"><h3>Business hours</h3><p>Monday–Saturday · 09:00–18:00<br>Lunch break · 13:00–14:00<br>Sunday · Closed<br>Bookings open 60 days ahead, in 15-minute increments.<br>Timezone: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)} (device local; demo only).</p><label>Close a date<input type="date" id="closed-date"></label><button class="secondary" id="add-closure">Add closure</button><p>${state.settings.closedDates.map(d=>`${d} <button class="text-link" data-remove-closure="${d}">Reopen ×</button>`).join('<br>')||'No additional closures.'}</p><p>Closures prevent new bookings. Review and reschedule existing appointments separately.</p></section><section class="panel settings-card"><h3>Data & connection</h3><p>Demo data is stored on this browser only. Use fictional records in the local demo. Sign in to save your private workspace across devices.</p><div class="actions"><button id="export-data">Export demo data</button><button id="reset-data" class="danger">Clear demo data</button><button id="firebase-info">Account & connection</button></div></section><section class="panel settings-card"><h3>Try a busier day</h3><p>Load fictional appointments and a sample queue to explore staff workflows. Existing records are kept.</p><button id="sample-data" class="secondary">Load sample day</button><p>Demo roles share this browser’s data. Customer view is a preview, not an access boundary.</p></section></div>`;}
function customer(){return `<div class="pill-note">Customer view preview · All demo data is visible in this browser. Use fictional details only.</div><section class="customer-hero"><small>STUDIO & CO. / YOUR TIME MATTERS</small><h2>A little less waiting.<br>A little more living.</h2><p>Book a time that works for you. Check in up to 30 minutes before your appointment and follow the queue right here.</p><button class="primary" data-book>Find your next appointment ↗</button></section><div class="service-grid">${services.map(s=>`<section class="panel service-card"><small class="eyebrow">${s.minutes} MINUTES, JUST FOR YOU</small><h3>${s.name}</h3><p>PKR ${s.price.toLocaleString()} · Pay at the business</p><button class="primary" data-service="${s.id}">Choose service ↗</button></section>`).join('')}</div><div class="lower">${appointments(false)}${queue()}</div>`;}
function render(){const continuity=captureView($('#content'));const titles={overview:['A good day starts here.','A clear view of your appointments, your team, and who’s up next.'],appointments:['A place for every appointment.','Book, check in, reschedule, and keep the day moving.'],queue:['Less waiting. More flow.','Help the next person, one smooth handoff at a time.'],team:['Good people. Great days.','Keep availability clear and your team in sync.'],settings:['Make it work for you.','Your hours, queue, and demo workspace controls.'],customer:['Make a little time for yourself.','Welcome to Studio & Co. Choose your service and we’ll make room.']};$('#page-title').textContent=titles[view][0];$('#page-subtitle').textContent=titles[view][1];$('#crumb').textContent=view==='customer'?'Customer booking':view[0].toUpperCase()+view.slice(1);$('#today-label').textContent=new Date().toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase();$('#nav-count').textContent=todayEntries().length;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));$('#content').innerHTML=cloudMode&&['signed-out','loading','verify-email','error'].includes(cloudStatus)?'<section class="panel settings-card"><h2>Private workspace locked</h2><p>Open Account & connection to sign in, verify your email, or retry. Your records appear after your connection is confirmed.</p><button id="firebase-info" class="secondary">Account & connection</button></section>':view==='overview'?`${stats()}<div class="dashboard-grid">${appointments(true)}${queue()}</div><div class="lower">${team(true)}<aside class="tip"><small>A SMOOTHER DAY, BY DESIGN</small><h3>Give every customer their time.</h3><p>Keep your queue moving with a quick check-in and a clear next step. Small moments make a big difference.</p></aside></div>`:view==='appointments'?appointments():view==='queue'?`${stats()}${queue()}`:view==='team'?team():view==='settings'?settings():customer();if(cloudMode)syncCloudLabels();restoreView($('#content'),continuity);connection();}
function openBooking(id=null,service=null){if(operations.busy)return feedback('Wait for the current save to finish.');if(cloudMode&&(!cloudReady||!navigator.onLine))return feedback('Connect to your workspace before booking.');if(id&&!state.entries.some(e=>e.id===id&&e.status==='booked'))return feedback('This appointment changed. Select it again.');editId=id;const f=$('#booking-form');f.reset();$('#form-error').textContent='';$('#service-select').innerHTML=services.map(s=>`<option value="${s.id}">${s.name}</option>`).join('');$('#staff-select').innerHTML=staff.map(n=>`<option>${n}</option>`).join('');f.elements.date.min=localDay();const max=new Date();max.setDate(max.getDate()+60);f.elements.date.max=localDay(max);f.elements.date.value=localDay();if(id){const e=state.entries.find(e=>e.id===id);for(const k of ['name','phone','service','staff','date'])f.elements[k].value=e[k];}if(service)f.elements.service.value=service;$('#modal-title').textContent=id?'Reschedule appointment':'New appointment';f.dataset.requestId=crypto.randomUUID();updateSlots();if(id)f.elements.time.value=state.entries.find(e=>e.id===id).time;$('#booking-dialog').showModal();}
function updateSlots(){const f=$('#booking-form'),s=services.find(s=>s.id===f.elements.service.value);$('#booking-summary').textContent=`${s.minutes} minutes · PKR ${s.price.toLocaleString()} · Pay at the business`;const prev=f.elements.time.value;let slots='';for(let m=540;m<1080;m+=15){const input={name:'Slot check',phone:'0000000000',service:s.id,staff:f.elements.staff.value,date:f.elements.date.value,time:clock(m)};try{validate(state,input,new Date(),editId);slots+=`<option value="${clock(m)}">${clock(m)}</option>`;}catch{}}$('#time-select').innerHTML=slots||'<option value="">No available slots</option>';if([...f.elements.time.options].some(o=>o.value===prev))f.elements.time.value=prev;f.querySelector('[type=submit]').disabled=!slots;}
$('#booking-form').addEventListener('change',e=>{if(['service','staff','date'].includes(e.target.name))updateSlots();});
$('#booking-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=f.querySelector('[type=submit]');b.disabled=true;$('#form-error').textContent='';const targetId=editId;const input=Object.fromEntries(new FormData(f));input.requestId=f.dataset.requestId;try{validate(state,input,new Date(),targetId);const ok=await mutate(s=>book(s,input,new Date(),targetId));if(ok){$('#booking-dialog').close();toast(editId?'Appointment rescheduled.':'Appointment booked. No reminders were sent.');}}catch(err){$('#form-error').textContent=err.message;}finally{updateSlots();}});
function confirm(title,copy,fn){$('#confirm-title').textContent=title;$('#confirm-copy').textContent=copy;pending=fn;$('#confirm-dialog').showModal();}
$('#confirm-action').addEventListener('click',async()=>{const fn=pending;pending=null;$('#confirm-dialog').close();if(fn)await fn();});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.close&&operations.busy){feedback('Saving changes. Please wait before closing.');return;}if(b.dataset.close){$('#'+b.dataset.close).close();return;}
 if(b.dataset.view==='customer'&&cloudMode){toast('Customer view is only available in the local demo.');return;}if(b.dataset.view){view=b.dataset.view;search='';filter='all';date=localDay();closeNav();render();window.scrollTo(0,0);$('#page-title').focus({preventScroll:true});return;}
 if(b.dataset.book!==undefined||b.id==='new-booking'){openBooking();return;}
 if(b.dataset.service){openBooking(null,b.dataset.service);return;}
 if(b.dataset.edit){openBooking(b.dataset.edit);return;}
 if(b.dataset.filter){filter=b.dataset.filter;render();return;}
 if(b.dataset.action){const run=async()=>{if(await mutate(s=>transition(s,b.dataset.id,b.dataset.action)))toast('Appointment updated.');};if(['cancelled','noshow'].includes(b.dataset.action))confirm(b.dataset.action==='cancelled'?'Cancel this appointment?':'Mark as a no-show?',b.dataset.action==='cancelled'?'This releases the slot. Cancelled appointments cannot be restored; create a new booking if needed.':'Only mark a no-show after the 15-minute grace period. This releases the slot.',run);else await run();return;}
 if(b.dataset.away){const away=state.settings.away.includes(b.dataset.away);await mutate(s=>({...s,settings:{...s.settings,away:away?s.settings.away.filter(n=>n!==b.dataset.away):[...s.settings.away,b.dataset.away]}}));return;}
 if(b.dataset.removeClosure){await mutate(s=>({...s,settings:{...s.settings,closedDates:s.settings.closedDates.filter(d=>d!==b.dataset.removeClosure)}}));return;}
 if(b.id==='customer-view'&&cloudMode){toast('Customer view is only available in the local demo.');return;}if(b.id==='customer-view'){view='customer';render();}
 if(b.id==='menu'){const open=!document.body.classList.contains('nav-open');document.body.classList.toggle('nav-open',open);$('.sidebar').classList.toggle('open',open);b.setAttribute('aria-expanded',String(open));}
 if(['connection-info','firebase-info'].includes(b.id)&&!cloudMode)$('#info-dialog').showModal();
 if(b.id==='pause-queue'){const paused=!state.settings.paused;if(await mutate(s=>({...s,settings:{...s.settings,paused}})))toast(paused?'New check-ins paused.':'Check-ins resumed.');}
 if(b.id==='save-capacity'){const cap=Number($('#capacity').value);if(!Number.isInteger(cap)||cap<1||cap>100){toast('Capacity must be a whole number from 1 to 100.');return;}if(await mutate(s=>({...s,settings:{...s.settings,capacity:cap}}))){delete $('#capacity').dataset.dirty;$('#capacity').value=cap;toast('Queue capacity saved. Existing customers remain in the queue.');}}
 if(b.id==='add-closure'){const d=$('#closed-date').value;if(!d||d<localDay()){toast('Choose today or a future date.');return;}confirm('Close this date?',`New bookings for ${d} will be blocked. Review existing appointments and contact affected customers separately.`,()=>mutate(s=>({...s,settings:{...s.settings,closedDates:[...new Set([...s.settings.closedDates,d])]}})));}
 if(b.id==='reset-data')confirm(cloudMode?'Clear your cloud workspace?':'Clear all demo data?',cloudMode?'This replaces your private cloud workspace with an empty one across your devices. Export a copy first.':'This permanently deletes the appointments and settings stored by this demo in this browser.',()=>mutate(()=>empty()));
 if(b.id==='sample-data'&&cloudMode){toast('Sample data is available in the local demo only.');return;}if(b.id==='sample-data'){const saved=await mutate(s=>{const today=localDay(),names=['Jordan Lee','Amelia Carter','Noah Williams','Isabella Chen','Ethan Brooks','Mia Patel'],statuses=['serving','waiting','waiting','booked','completed','booked'];if(s.entries.some(e=>e.date===today))throw Error('Sample data requires an empty day to avoid conflicts with existing bookings.');const sample=names.map((name,i)=>({id:crypto.randomUUID(),name,phone:'+92 300 00000'+String(i).padStart(2,'0'),service:i===1?'followup':'consult',staff:staff[i%3],date:today,time:['09:00','09:30','10:00','10:30','11:00','11:30'][i],status:statuses[i],ticket:i<3?i+1:null,sample:true,createdAt:new Date().toISOString()}));return {...s,entries:[...s.entries,...sample]};});if(saved)toast('Fictional sample day loaded.');}
 if(b.id==='export-data'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='queueflow-demo-'+localDay()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
});
document.addEventListener('change',e=>{if(e.target.id==='date-filter'){date=e.target.value||localDay();render();}if(e.target.id==='other-status'){filter=e.target.value;render();}});
document.addEventListener('input',e=>{if(['capacity','closed-date'].includes(e.target.id))e.target.dataset.dirty='true';if(e.target.id==='search'){const cursor=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(cursor,cursor);}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(operations.busy)return;if(e.target===d&&e.clientX){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
function closeNav(){document.body.classList.remove('nav-open');$('.sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');syncViewport();}
$('#nav-scrim').addEventListener('click',closeNav);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNav();});document.addEventListener('cancel',e=>{if(operations.busy)e.preventDefault();},true);$('#confirm-dialog').addEventListener('close',()=>{pending=null;});const syncViewport=installViewportManager();
render();
function syncCloudLabels(){
 document.querySelector('.demo-pill').textContent=cloudReady?'● Connected':'● Cloud workspace locked';
 document.querySelector('.profile b').textContent=cloudUser?'Private business workspace':'Sign-in required';
 document.querySelector('.profile small').textContent=cloudUser?.email||'No cloud data loaded';
 document.querySelector('.business small').textContent='Private workspace';document.getElementById('cloud-account').textContent=cloudUser?'Account':'Sign in';
 document.querySelector('.connection-banner div').textContent=cloudReady?'Your changes are saved across your devices.':'Cloud data is locked until sign-in, email verification and a server connection complete.';
 document.getElementById('save-status').textContent=cloudReady?'All changes saved':'Connection required · Changes locked';
 document.getElementById('cloud-logout').hidden=!cloudUser;
 document.getElementById('customer-view').hidden=true;
 document.getElementById('new-booking').disabled=!cloudReady;
 document.querySelectorAll('[data-book]').forEach(button=>{button.disabled=!cloudReady||!navigator.onLine;});
 document.querySelectorAll('.live').forEach(label=>{label.textContent=state.settings.paused?'● PAUSED':cloudReady?'● SYNCED':'● LOCKED';});
 const bookingNote=document.querySelector('#booking-form > small.muted');if(bookingNote)bookingNote.textContent='Saved privately to your workspace.';
 const cards=document.querySelectorAll('.settings-card');
 if(view==='settings'&&cards[2]){cards[2].querySelector('p').textContent='Your workspace is private to your account. Export a copy of your records or manage your account below.';cards[3].hidden=true;document.getElementById('page-subtitle').textContent='Your hours, queue, and private owner workspace controls.';document.getElementById('export-data').textContent='Export cloud workspace';document.getElementById('reset-data').textContent='Clear cloud workspace';document.getElementById('firebase-info').textContent='Account & connection';}
}
const cloudStatusText={loading:'Signing in and loading your workspace…','signed-out':'Sign in to open your private workspace.','verify-email':'Verify your email before accessing data. Use the verification controls below.',connecting:'Reconnecting. Editing is paused.',connected:'Your workspace is connected.',error:'Connection failed. Your workspace is locked.'};
import {installCloudControls} from './cloud-controls.js?v=20261023-account1';
installCloudControls({
 isCloud(){return cloudMode;},
 busy(){return operations.busy;},
 begin(){if(!cloudMode){operations.reset();cloudMode=true;cloudReady=false;state=empty();view='overview';const url=new URL(location.href);url.searchParams.set('workspace','cloud');history.replaceState(null,'',url);render();}},
 state(next){state=next;render();},
 status(status,user,error){const changed=cloudStatus!==status||cloudUser?.uid!==user?.uid;if(cloudUser?.uid!==user?.uid){operations.reset();document.querySelectorAll('[data-dirty]').forEach(el=>delete el.dataset.dirty);$('#workspace-message').hidden=true;pending=null;editId=null;$('#booking-dialog').close();$('#confirm-dialog').close();}cloudStatus=status;cloudReady=status==='connected';cloudUser=user||null;const text=error?(cloud?.message(error)||cloudStatusText.error):cloudStatusText[status];document.dispatchEvent(new CustomEvent('queueflow-cloud-status',{detail:{status,text,user:user?{email:user.email,emailVerified:user.emailVerified}:null}}));if(changed)render();else{syncCloudLabels();connection();}},
});
// Keep the SDK lazy for demo visitors; cloud mutations use the same module instance.
document.getElementById('cloud-account').addEventListener('click',async()=>{try{cloud=await import('./firebase-client.js?v=20261023-state1');}catch{}});
if(new URLSearchParams(location.search).get('workspace')==='cloud')import('./firebase-client.js?v=20261023-state1').then(sdk=>{cloud=sdk;}).catch(()=>{});
